chan-pipeline.source:
@main

fn produce(output chan int) {
    for value in 1:6 {
        output <- value
    }
}

fn square(input chan int, output chan int) {
    for i in 0:5 {
        value := <-input
        output <- value * value
    }
}

fn main() int {
    numbers := chan int{cap: 2}
    squares := chan int{cap: 2}
    xu produce(numbers)
    xu square(numbers, squares)
    for i in 0:5 {
        value := <-squares
        println(value)
    }
    << 0
}

coroutine.source:
@main

fn worker(id int, ch chan int) {
    println("协程 #" + str(id) + " 运行中...")
    ch <- id * 10
}

fn main() int {
    ch := chan int{cap: 3}
    // 使用 xu f() 并发启动轻量协程
    xu worker(1, ch)
    xu worker(2, ch)
    xu worker(3, ch)

    mut sum := 0
    for i in 0:3 {
        val := <-ch
        sum += val
    }
    println("汇总结果: " + str(sum))
    << 0
}

ui-counter.source:
@main
#ui/draw
#playground

fn render(count int) {
    draw.begin()
    draw.set_bg("#101827")
    draw.text(32, 28, 26, "#f8fafc", "Xu / Interactive UI")
    draw.text(32, 70, 16, "#94a3b8", "Click a button. Xu updates the state and draws again.")
    draw.text(32, 126, 42, "#f8fafc", "Count: " + str(count))
    draw.round_rect(240, 174, 160, 64, 14, "#e11d48", "-", 1)
    draw.text(296, 190, 26, "#ffffff", "+1")
    draw.round_rect(424, 174, 176, 64, 14, "#1e293b", "#475569", 2)
    draw.text(476, 194, 20, "#e2e8f0", "Reset")
    draw.fill_circle(58 + count % 14 * 40, 292, 10, "#38bdf8")
    draw.text(32, 322, 14, "#94a3b8", "State + hit testing: Xu   /   Pixels + pointer: Canvas")
    draw.present()
}

fn main() int {
    mut count := 0
    render(count)
    while true {
        click := playground.next_click()
        if click.ok == 0 { <- }
        if draw.in_rect(click, 240, 174, 160, 64) { count += 1 }
        if draw.in_rect(click, 424, 174, 176, 64) { count = 0 }
        render(count)
    }
    println("Count: " + str(count))
    << 0
}

ui-widgets.source:
@main
#ui
#ui/draw
#ui/layout
#ui/widgets
#playground

fn demo() int {
    identity := playground.canvas_identity()
    context := draw.default_context()
    options := draw.text_options(17.0)
    button_text := "+1 / Button"
    check_text := "Checkbox"
    switch_text := "Switch"
    button_label := context.layout_text(&button_text,&options) or >>
    check_label := context.layout_text(&check_text,&options) or >>
    switch_label := context.layout_text(&switch_text,&options) or >>
    // Real widgets measurement determines the button's layout bounds.
    measured := widgets.button_size(&button_label)
    button_bounds := layout.Rect{x: 32.0,y: 100.0,width: measured.width + 24.0,height: measured.height + 12.0}
    check_bounds := layout.Rect{x: 32.0,y: 170.0,width: 252.0,height: 36.0}
    switch_bounds := layout.Rect{x: 32.0,y: 224.0,width: 252.0,height: 36.0}
    slider_bounds := layout.Rect{x: 336.0,y: 174.0,width: 264.0,height: 36.0}
    mut button := widgets.button(&identity,1,&button_bounds) or >>
    mut check := widgets.checkbox(&identity,2,&check_bounds,false) or >>
    mut toggle := widgets.switch_control(&identity,3,&switch_bounds,false) or >>
    mut slider := widgets.slider(&identity,4,&slider_bounds,0.0,100.0,40.0) or >>
    slider.set_step(5.0) or >>
    mut count := 0
    mut focus := 0
    while true {
        input := playground.next_input()
        if input.kind == 0 { <- }
        if input.kind == ui.EV_KEY_DOWN && input.key == ui.KEY_TAB {
            if (input.modifiers & ui.MOD_SHIFT) != 0 {
                focus = (focus + 2) % 4 + 1
            } else { focus = focus % 4 + 1 }
            button.set_focus(focus == 1)
            check.set_focus(focus == 2)
            toggle.set_focus(focus == 3)
            slider.set_focus(focus == 4)
        }
        action := button.input(&input)
        check_action := check.input(&input)
        switch_action := toggle.input(&input)
        slider_action := slider.input(&input)
        if action.kind == widgets.ACTION_ACTIVATE { count += 1 }
        if action.request_focus { focus = 1 }
        if check_action.request_focus { focus = 2 }
        if switch_action.request_focus { focus = 3 }
        if slider_action.request_focus { focus = 4 }
        if input.kind == ui.EV_POINTER_CANCEL { focus = 0 }
        if input.kind == ui.EV_POINTER_DOWN || input.kind == ui.EV_POINTER_CANCEL {
            button.set_focus(focus == 1)
            check.set_focus(focus == 2)
            toggle.set_focus(focus == 3)
            slider.set_focus(focus == 4)
        }
    }
    theme := widgets.default_theme()
    mut frame := context.new_frame(4096)
    frame.begin() or >>
    frame.clear(draw.rgb(16,24,39)) or >>
    draw.text(32, 24, 26, "#f8fafc", "Xu / Real widgets")
    draw.text(32, 64, 14, "#94a3b8", "#ui/widgets  /  shared desktop logic  /  WASM")
    draw.text(336, 105, 30, "#f8fafc", "Count: " + str(count))
    button.paint(mut &frame,&button_label,&theme) or >>
    check.paint(mut &frame,&check_label,&theme) or >>
    toggle.paint(mut &frame,&switch_label,&theme) or >>
    slider.paint(mut &frame,&theme) or >>
    draw.text(336, 222, 18, "#e2e8f0", "Slider: " + str(int(slider.value())))
    draw.text(336, 256, 14, "#94a3b8", "Click track / Arrow keys / Home / End")
    draw.text(32, 314, 14, "#94a3b8", "Tab: focus  /  Enter or Space: activate  /  Esc: leave")
    frame.present() or >>
    button.painted()
    check.painted()
    toggle.painted()
    slider.painted()
    println("Count: " + str(count) + " | Checkbox: " + str(check.value()) + " | Switch: " + str(toggle.value()) + " | Slider: " + str(int(slider.value())))
    << 0
}

fn main() int {
    << demo() or (err) {
        eprintln(err.msg())
        << 1
    }
}
